#!/usr/bin/env python3
from pathlib import Path
import json,shutil
root=Path(__file__).resolve().parents[1];out=root/'docs/gameplay2'
n=json.loads((root/'build/gameplay2-native-touch.json').read_text());e=json.loads((root/'build/gameplay2-effects-performance.json').read_text())
r=['# Godot performans ölçümleri — Oynanış 2.0','','Godot 4.6.3, --profiling, Linux/Xvfb :99, 540×960, Mesa llvmpipe LLVM19.1.7 yazılım rendererı, 60 FPS sınırlayıcı. Nihai koşuda renderer thread limiti yoktur; bulut CPU kotası 4 vCPU. Telefon/emülatör bağlı değildir. Bunlar Android ölçümü değildir.','','100 geçerli ScreenTouch kaydırma, 100 engellenen tekrar, 10 geçersiz takas; 76–100 arasındaki 25 bölüm. Mantık/kararlı tahta doğrulamaları geçti. Native benchmark kendi test profiline senkron kayıt yazar; gerçek uygulama arka plan yazıcı kullanır. Sahne geçişleri ve test çözücüsü kare istatistiğine dahildir.','','| Ölçüm | Ortalama | p95 | Maksimum |','|---|---|---|---|']
f=n['frame_interval_ms'];r.append(f"| Kare aralığı ({f['count']} kare) | {f['mean']:.3f} ms / {1000/f['mean']:.2f} FPS | {f['p95']:.3f} ms | {f['max']:.3f} ms |")
labels={'touch_callback':'Dokunma callback','touch_to_visual_submit':'Dokunma → görsel CPU gönderimi','drag_motion_to_visual_submit':'Sürükleme → görsel CPU gönderimi','swap_and_cascades':'Takas ve bütün zincir mantığı','match_scan':'Eşleşme taraması','clear_logic':'Temizleme','gravity_logic':'Yer çekimi','refill_logic':'Dolum','storm_logic':'Fırtına taşıma','crystal_wave_logic':'Dalga boyama','board_draw_cpu':'Tahta çizim komutları CPU','animation_swap':'Takas animasyonu','animation_revert':'Geçersiz geri dönüş','render_cpu':'Render CPU monitorü','render_gpu':'Render GPU zaman sorgusu'}
for key,label in labels.items():
 m=n['diagnostics']['metrics'][key];r.append(f"| {label} | {m['mean_ms']:.3f} ms | {m['p95_ms']:.3f} ms | {m['max_ms']:.3f} ms |")
r+=['','**Tekil gecikme gizlenmedi:** en uzun kare 566,773 ms; GPU zaman sorgusu en çok 562,704 ms. Mantık takası en çok 37,091 ms, temizleme 30,596 ms oldu. Bütün karelerde 16,7 ms bütçesi karşılanmadı. Yazılım rendererı/host beklemesi gözlenir; Android sürücüsü, OS input kuyruğu ve gerçek cihazdaki takılmanın nedeni bu ölçümden kesinleşmez.','', 'Dokunma/görsel süresi CPU çizim gönderimidir; fiziksel parmak→Android→ekran gecikmesi değildir. Performance.TIME_PROCESS, engine process zamanıdır; bağımsız CPU çevrim sayımı değildir. Monitorler son 2.048 örneği, kare tablosu 14.009 karenin tamamını kullanır.','','## Altı birleşim, iki kalite','', 'Her birleşim dengeli/performans ayarında iki kez: 24 gerçek render senaryosu. Fırtına hazırdı; otomatik zincirler tamamlandı, kaskad koruması tetiklenmedi.','','| Kalite | Birleşim | Mantık aralığı | Kare ortalaması | En kötü p95 |','|---|---|---|---|']
for quality in ['balanced','performance']:
 for combo in ['rocket_rocket','rocket_prism','prism_prism','color_rocket','color_prism','color_color']:
  a=[x for x in e['scenarios'] if x['quality']==quality and x['combo']==combo];avg=sum(x['mean_frame_ms']*x['frame_samples'] for x in a)/sum(x['frame_samples'] for x in a)
  r.append(f"| {quality} | {combo} | {min(x['logic_ms'] for x in a):.3f}–{max(x['logic_ms'] for x in a):.3f} ms | {avg:.3f} ms / {1000/avg:.2f} FPS | {max(x['p95_frame_ms'] for x in a):.3f} ms |")
c=n['diagnostics']['counters'];r+=['',f"Native static-memory monitorü en çok {c['peak_static_memory_bytes']/1048576:.2f} MiB, canlı nesne monitorü {c['peak_live_objects']}. Birleşimlerin tümü 6 tahta çocuğu / 192 sabit partikül slotuyla bitti. Kesin tahsis-adedi/byte-allocation profili ölçülmedi; nesne/bellek monitorü bunu kanıtlamaz.", '', 'Koruma: kaliteye bağlı partikül bütçesi, sabit etiket/efekt havuzları, merkezi tekilleştirilmiş güç alanları ve doğuş hücresi önbelleği kullanılır. Her blok için yeni sahne/texture yüklenmez. Animasyon sonunda current={} yerel referansı bırakır; mantıksal olay sözlüğü clear() ile silinmez. Metadata değişmezlik testleri vardır.','', 'Android FPS/p95/max, uzun kullanımda pil/ısı, fiziksel dokunma, hoparlör/haptik, gerçek çentik/sistem çubukları, APK kurulum ve cihaz arka plan/geri dönüş kabulü henüz doğrulanmadı. Desktop/headless pause/resume ve safe-area testleri bunların yerine sunulmaz.','', '[Ham native JSON](performance/gameplay2-native-touch.json) · [Ham birleşim JSON](performance/gameplay2-effects-performance.json). APK içinde Ayarlar → Performans raporu kullanılabilir.']
(out/'PERFORMANCE.md').write_text('\n'.join(r)+'\n')
(out/'performance/measurement-provenance.json').write_text(json.dumps({'engine':'4.6.3','flags':['--profiling','--audio-driver Dummy','--max-fps 60'],'display':':99','viewport':[540,960],'renderer':e['renderer'],'platform':'Linux','android_devices':[],'native_valid_swipes':100,'duplicate_blocked':100,'invalid_swaps':10,'combination_scenarios':24,'native_saves':'synchronous test profile; application uses worker','all_frames_under_16_7ms':False,'phone_fps_verified':False},indent=2)+'\n')
for p in (root/'build').glob('gameplay2-*.png'):
 if 'probe' not in p.name:shutil.copyfile(p,out/'screens'/p.name)
